options.helpers:
const valid = value => typeof value === 'number' && Number.isFinite(value);
context.handlebars.registerHelper('share', value => valid(value) ? value.toFixed(1) + '%' : 'Unknown');
context.handlebars.registerHelper('memory', value => !valid(value) ? 'Unknown' : value >= 1073741824 ? (value / 1073741824).toFixed(1) + ' GiB' : (value / 1048576).toFixed(0) + ' MiB');

const rank = {critical: 0, error: 1, warning: 2, info: 3};
const weight = row => Object.prototype.hasOwnProperty.call(rank, row.severity) ? rank[row.severity] : 4;
const title = value => String(value || 'Unknown alert').replace(/([A-Z])([A-Z][a-z])/g, '$1 $2').replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/_/g, ' ');
const labels = {name: 'Container', instance: 'Target', job: 'Monitor', queue: 'Queue', mountpoint: 'Filesystem', device: 'Device', service: 'Service', application: 'Application', environment: 'Environment', platform: 'Platform', container_label_com_docker_compose_project: 'Project'};
context.handlebars.registerHelper('alertRows', rows => Array.isArray(rows) ? rows.filter(row => row && row.alertname).slice().sort((left, right) => weight(left) - weight(right) || String(left.alertname).localeCompare(String(right.alertname))) : []);
context.handlebars.registerHelper('alertTitle', title);
context.handlebars.registerHelper('severityText', value => value ? String(value).charAt(0).toUpperCase() + String(value).slice(1) : 'Severity unknown');
context.handlebars.registerHelper('severityClass', value => Object.prototype.hasOwnProperty.call(rank, value) ? 'severity-' + value : 'severity-unknown');
context.handlebars.registerHelper('alertDetails', row => Object.entries(row || {}).filter(([key, value]) => !['alertname', 'severity', 'alertstate', 'demo', '__name__'].includes(key) && !/^(Time|Value)(?: |$)/.test(key) && value !== null && value !== undefined && value !== '').map(([key, value]) => ({label: labels[key] || title(key), value: String(value)})));
